// Test_decide runs the slice's specifications: the given events replayed
// through evolve, then decide with the command.
func Test_decide(t *testing.T) {
	tests := []struct {
		name    string
		history []eventsourcing.Event
		cmd     PublishCart
		want    []eventsourcing.Event
		wantErr error
		skip    string
	}{
		{
			name: "spec: Publish Cart - A submitted cart is published",
			history: []eventsourcing.Event{
				&events.CartCreated{CartID: cartID},
				&events.ItemAdded{CartID: cartID, ItemID: itemID, ProductID: productID, Description: "Espresso beans", Price: 12.5},
				&events.CartSubmitted{CartID: cartID},
			},
			cmd: PublishCart{CartID: cartID},
			want: []eventsourcing.Event{
				&events.CartPublished{CartID: cartID},
			},
		},
		{
			name: "spec: Publish Cart - Publishing again records nothing",
			history: []eventsourcing.Event{
				&events.CartCreated{CartID: cartID},
				&events.ItemAdded{CartID: cartID, ItemID: itemID, ProductID: productID, Description: "Espresso beans", Price: 12.5},
				&events.CartSubmitted{CartID: cartID},
				&events.CartPublished{CartID: cartID},
			},
			cmd: PublishCart{CartID: cartID},
		},
		{
			name: "spec: Publish Cart - Only a submitted cart is published",
			history: []eventsourcing.Event{
				&events.CartCreated{CartID: cartID},
			},
			cmd:     PublishCart{CartID: cartID},
			wantErr: errCartNotSubmitted,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if tt.skip != "" {
				t.Skip("TODO: " + tt.skip)
			}
			s := initialState()
			for _, e := range tt.history {
				s = evolve(s, &eventsourcing.Envelope{Event: e})
			}

			got, err := decide(s, tt.cmd)
			if !errors.Is(err, tt.wantErr) {
				t.Fatalf("decide() error = %v, want %v", err, tt.wantErr)
			}
			gotJSON, _ := json.Marshal(withoutGenerated(got))
			wantJSON, _ := json.Marshal(tt.want)
			if !bytes.Equal(gotJSON, wantJSON) {
				t.Errorf("decide() = %s, want %s", gotJSON, wantJSON)
			}
		})
	}
}

// withoutGenerated clears the fields the system fills in, which a
// specification cannot predict.
func withoutGenerated(in []eventsourcing.Event) []eventsourcing.Event {
	var out []eventsourcing.Event
	for _, e := range in {
		switch e := e.(type) {
		case *events.CartPublished:
			c := *e
			c.PublishedAt = time.Time{}
			out = append(out, &c)
			continue
		}
		out = append(out, e)
	}
	return out
}
